"""Static loopback login page. No external assets, QR image service or cloud calls."""
PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TeamAgent 登录</title><style>
body{font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;max-width:720px;margin:40px auto;padding:0 20px;color:#20283b;background:#f6f7fb}
h1{font-size:24px}section{background:#fff;border:1px solid #e2e6ee;border-radius:12px;padding:20px;margin:16px 0}
button{padding:9px 14px;border:1px solid #cbd2e1;border-radius:8px;background:#fff;cursor:pointer}button.primary{background:#4b4bd6;color:#fff;border-color:#4b4bd6}
button:disabled{opacity:.5;cursor:wait}.qr{width:260px;height:260px;display:block;margin:12px 0}.note{color:#6d768b;font-size:13px;line-height:1.7}
.error{color:#a84245}.ok{color:#16735a}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}
</style></head><body>
<h1>TeamAgent 登录</h1>
<p class="note">B 站二维码只在本机生成和显示；扫码确认后 Cookie 只写入本机 0600 文件。X 会在这台 Mac 上用 Edge 打开独立登录窗口。</p>
<section><h2>B 站</h2><p id="bili-status" role="status">准备中…</p><div id="qr"></div><p id="count" class="note"></p><div class="row"><button id="refresh" class="primary">获取二维码</button></div></section>
<section><h2>X</h2><p id="x-status" role="status">未打开</p><p class="note">会在本机 Edge 中打开 x.com；账号密码只填在 Edge 窗口里，本页不接收。</p><div class="row"><button id="x" class="primary">用 Edge 登录 X</button></div></section>
<script>
const KEY='team-local-session'; let session=sessionStorage.getItem(KEY)||'', poll=null, deadline=0, current=null, starting=false, timer=null, pollBusy=false;
const $=id=>document.getElementById(id);
const headers=()=>({'Content-Type':'application/json','X-TeamAgent-Local':'1',...(session?{'X-TeamAgent-Session':session}:{})});
async function call(path,body,method){const r=await fetch(path,{method:method||(body?'POST':'GET'),headers:headers(),body:body?JSON.stringify(body):undefined,cache:'no-store',referrerPolicy:'no-referrer'});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||('HTTP '+r.status));return j}
function qrMatrix(text){const bytes=new TextEncoder().encode(text),bits=[];if(bytes.length>240)throw Error('二维码内容过长');const push=(value,count)=>{for(let i=count-1;i>=0;i--)bits.push((value>>>i)&1)};push(4,4);push(bytes.length,16);for(const b of bytes)push(b,8);push(0,4);while(bits.length%8)bits.push(0);const data=[];for(let i=0;i<bits.length;i+=8)data.push(bits.slice(i,i+8).reduce((v,b)=>v*2+b,0));for(let pad=0;data.length<274;pad++)data.push(pad%2?0x11:0xec);const mul=(a,b)=>{let v=0;for(;b;b>>>=1){if(b&1)v^=a;a<<=1;if(a&256)a^=0x11d}return v};let div=[1],root=1;for(let i=0;i<18;i++){const next=Array(div.length+1).fill(0);div.forEach((n,j)=>{next[j]^=n;next[j+1]^=mul(n,root)});div=next;root=mul(root,2)}let off=0;const blocks=[68,68,69,69].map(len=>{const block=data.slice(off,off+=len),par=Array(18).fill(0);for(const byte of block){const f=byte^par.shift();par.push(0);for(let j=0;j<18;j++)par[j]^=mul(div[j+1],f)}return{block,parity:par}});const cw=[];for(let i=0;i<69;i++)for(const b of blocks)if(i<b.block.length)cw.push(b.block[i]);for(let i=0;i<18;i++)for(const b of blocks)cw.push(b.parity[i]);const size=57,m=Array.from({length:size},()=>Array(size).fill(false)),res=m.map(r=>r.slice());const mark=(x,y,d)=>{if(x>=0&&y>=0&&x<size&&y<size){m[y][x]=!!d;res[y][x]=true}};for(let i=0;i<size;i++){mark(6,i,i%2===0);mark(i,6,i%2===0)}for(const [cx,cy] of [[3,3],[53,3],[3,53]])for(let y=-4;y<=4;y++)for(let x=-4;x<=4;x++){const d=Math.max(Math.abs(x),Math.abs(y));mark(cx+x,cy+y,d!==2&&d!==4)}for(const cx of [6,28,50])for(const cy of [6,28,50]){if((cx===6&&cy===6)||(cx===6&&cy===50)||(cx===50&&cy===6))continue;for(let y=-2;y<=2;y++)for(let x=-2;x<=2;x++)mark(cx+x,cy+y,Math.max(Math.abs(x),Math.abs(y))!==1)}let rem=8;for(let i=0;i<10;i++)rem=(rem<<1)^((rem>>>9)*0x537);const fmt=((8<<10)|rem)^0x5412,bit=(v,n)=>(v>>>n)&1;for(let i=0;i<6;i++)mark(8,i,bit(fmt,i));mark(8,7,bit(fmt,6));mark(8,8,bit(fmt,7));mark(7,8,bit(fmt,8));for(let i=9;i<15;i++)mark(14-i,8,bit(fmt,i));for(let i=0;i<8;i++)mark(size-1-i,8,bit(fmt,i));for(let i=8;i<15;i++)mark(8,size-15+i,bit(fmt,i));mark(8,size-8,true);rem=10;for(let i=0;i<12;i++)rem=(rem<<1)^((rem>>>11)*0x1f25);const ver=(10<<12)|rem;for(let i=0;i<18;i++){const a=size-11+i%3,b=Math.floor(i/3);mark(a,b,bit(ver,i));mark(b,a,bit(ver,i))}let index=0;for(let right=size-1;right>0;right-=2){if(right===6)right--;for(let step=0;step<size;step++){const y=((right+1)&2)===0?size-1-step:step;for(let j=0;j<2;j++){const x=right-j;if(!res[y][x]){const dark=bit(cw[index>>>3]||0,7-(index&7));index++;m[y][x]=!!(dark^((x+y)%2===0))}}}}return m}
function drawQr(url){const matrix=qrMatrix(url),ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 65 65');svg.setAttribute('class','qr');svg.setAttribute('shape-rendering','crispEdges');const bg=document.createElementNS(ns,'rect');bg.setAttribute('width','65');bg.setAttribute('height','65');bg.setAttribute('fill','#fff');const path=document.createElementNS(ns,'path');path.setAttribute('fill','#000');path.setAttribute('d',matrix.flatMap((row,y)=>row.flatMap((dark,x)=>dark?['M'+(x+4)+','+(y+4)+'h1v1h-1z']:[])).join(''));svg.append(bg,path);return svg}
function countdown(){if(!deadline)return;const s=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('count').textContent=s?('二维码剩余 '+s+' 秒'):'二维码已过期';if(!s){clearInterval(poll);poll=null;current=null;$('qr').replaceChildren();$('count').textContent='';$('bili-status').textContent='二维码已过期，请重新获取';$('bili-status').className='error';deadline=0}}
async function start(){if(starting)return;starting=true;if(poll)clearInterval(poll);poll=null;current=null;$('qr').replaceChildren();$('bili-status').className='note';$('bili-status').textContent='正在向 B 站获取二维码…';try{const q=await call('/api/local/bili/start',{});current=q.id;starting=false;deadline=q.expires_at;$('qr').append(drawQr(q.qr_url));$('bili-status').textContent='等待扫码';$('bili-status').className='note';countdown();const myTimer=setInterval(async()=>{if(poll!==myTimer)return;if(pollBusy)return;pollBusy=true;try{const s=await call('/api/local/bili/status?id='+encodeURIComponent(current));if(poll!==myTimer)return;if(deadline&&Date.now()>=deadline){clearInterval(poll);poll=null;current=null;deadline=0;$('qr').replaceChildren();$('count').textContent='';$('bili-status').textContent='二维码已过期，请重新获取';$('bili-status').className='error'}else if(s.phase==='waiting'){$('bili-status').textContent='等待扫码';$('bili-status').className='note'}else if(s.phase==='scanned'){$('bili-status').textContent='已扫码，请在手机上确认';$('bili-status').className='ok'}else if(s.phase==='ok'){clearInterval(poll);poll=null;deadline=0;$('qr').replaceChildren();$('bili-status').textContent='B 站已登录';$('bili-status').className='ok';$('count').textContent=''}else if(s.phase==='expired'||s.phase==='failed'||s.phase==='paused'){clearInterval(poll);poll=null;current=null;deadline=0;$('qr').replaceChildren();$('count').textContent='';$('bili-status').textContent=s.error||(s.phase==='expired'?'二维码已过期，请重新获取':s.phase==='paused'?'B 站暂时限制，请稍后再试':'登录未完成，请重试');$('bili-status').className='error'}}catch(e){if(poll!==myTimer)return;$('bili-status').textContent=e.message;$('bili-status').className='error'}finally{pollBusy=false}},1200);poll=myTimer}catch(e){starting=false;$('bili-status').textContent=e.message;$('bili-status').className='error'}}
async function unlock(){const m=location.hash.match(/unlock=([A-Za-z0-9_-]+)/);if(m){try{const r=await fetch('/api/local/session',{method:'POST',headers:{'Content-Type':'application/json','X-TeamAgent-Local':'1'},body:JSON.stringify({code:m[1]})});const j=await r.json();if(!r.ok)throw Error(j.error||'解锁失败');session=j.session;sessionStorage.setItem(KEY,session);history.replaceState(null,'',location.pathname)}catch(e){$('bili-status').textContent=e.message;$('bili-status').className='error';return}}if(!session){$('bili-status').textContent='请双击桌面 TeamAgent-登录 解锁本机页面';return}start()}
$('refresh').onclick=start;$('x').onclick=async()=>{try{await call('/api/local/x/open',{});$('x-status').textContent='已在本机 Edge 打开登录窗口';$('x-status').className='ok'}catch(e){$('x-status').textContent=e.message;$('x-status').className='error'}};setInterval(countdown,500);unlock()
</script></body></html>'''
